function generate(rand, size) {
  const pick = count => Math.floor(rand() * count);
  const n = size === 'large' ? 90 + pick(11) : 2 + pick(7);
  // Values from tiny ranges make long runs of equal parity; 1..100 covers the full range.
  const top = [2, 3, 100][pick(3)];
  return [Array.from({ length: n }, () => 1 + pick(top))];
}
